<?php require 'config.php'; need(['nurse','doctor','records']); check();
$pid=(int)($_GET['pid']??$_POST['pid']??0);$sq=trim($_GET['q']??'');$msg=$err='';
$q=function($sql,$a=[])use($pdo){$s=$pdo->prepare($sql);$s->execute($a);return $s->fetchAll();};
$SCH=[['BCG',1,0],['OPV',0,0],['OPV',1,6],['OPV',2,10],['OPV',3,14],['Pentavalent',1,6],['Pentavalent',2,10],['Pentavalent',3,14],['PCV10',1,6],['PCV10',2,10],['PCV10',3,14],['Rotavirus',1,6],['Rotavirus',2,10],['IPV',1,14],['Measles-Rubella',1,39],['Measles-Rubella',2,78]];
function nut_class($mo,$muac,$oed,$w,$h){
  if($mo<60&&$oed)return ['SAM (severe acute malnutrition)','Refer for stabilization and therapeutic feeding (RUTF). Review weekly.'];
  if($mo>=6&&$mo<60&&$muac!==null){if($muac<115)return ['SAM (severe acute malnutrition)','Refer for stabilization and therapeutic feeding (RUTF). Review weekly.'];if($muac<125)return ['MAM (moderate acute malnutrition)','Start supplementary feeding, counsel the caregiver and review in 2 weeks.'];return ['Normal','Continue breastfeeding and a balanced diet. Review at the next visit.'];}
  if($mo>=228&&$w&&$h){$b=$w/pow($h/100,2);if($b<18.5)return ['Underweight (BMI '.round($b,1).')','Dietary counselling and look for the cause.'];if($b<25)return ['Normal (BMI '.round($b,1).')','Keep a balanced diet and stay active.'];if($b<30)return ['Overweight (BMI '.round($b,1).')','Diet and exercise counselling.'];return ['Obese (BMI '.round($b,1).')','Diet, exercise and review for related conditions.'];}
  return ['Recorded','Plot the weight and height on the growth chart.'];}
$P=null;if($pid){$P=$q('SELECT * FROM patients WHERE id=?',[$pid]);$P=$P[0]??null;if(!$P)die('Patient not found.');}
if($P){$di=(new DateTime($P['dob']))->diff(new DateTime());$mo=$di->y*12+$di->m;$wk=(int)floor((time()-strtotime($P['dob']))/604800);}
if($_SERVER['REQUEST_METHOD']==='POST'&&$P){
  $ins=function($kind,$item,$dose,$batch,$next)use($pdo,$pid){$pdo->prepare('INSERT INTO immunization_records(patient_id,kind,item,dose_no,given_at,batch_no,next_due,given_by) VALUES(?,?,?,?,CURDATE(),?,?,?)')->execute([$pid,$kind,$item,$dose,trim($batch),$next,user()['id']]);audit("$kind $item patient $pid");};
  try{
    if(isset($_POST['vac'])){$item=trim($_POST['item']);$dose=$_POST['dose']===''?null:(int)$_POST['dose'];
      if($item===''||($dose!==null&&($dose<0||$dose>10)))$err='Enter the vaccine and a valid dose number.';else{$ins('vaccine',$item,$dose,$_POST['batch'],null);$msg=$item.' recorded.';}}
    elseif(isset($_POST['vita'])){$ins('vitamin_a','Vitamin A',null,$_POST['batch']??'',date('Y-m-d',strtotime('+6 months')));$msg='Vitamin A recorded.';}
    elseif(isset($_POST['worm'])){$ins('deworming','Albendazole',null,$_POST['batch']??'',date('Y-m-d',strtotime('+6 months')));$msg='Deworming recorded.';}
    elseif(isset($_POST['nut'])){$w=$_POST['w']===''?null:(float)$_POST['w'];$h=$_POST['h']===''?null:(float)$_POST['h'];$mu=$_POST['muac']===''?null:(int)$_POST['muac'];
      if(($w!==null&&($w<0.5||$w>300))||($h!==null&&($h<30||$h>250))||($mu!==null&&($mu<50||$mu>400)))$err='Check the weight, height or MUAC values.';
      else{$c=nut_class($mo,$mu,isset($_POST['oed'])?1:0,$w,$h);$pdo->prepare('INSERT INTO nutrition_assessments(patient_id,weight_kg,height_cm,muac_mm,oedema,classification,advice,notes,assessed_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$pid,$w,$h,$mu,isset($_POST['oed'])?1:0,$c[0],$c[1],trim($_POST['notes']),user()['id']]);audit("nutrition patient $pid");$msg='Assessment saved: '.$c[0].'.';}}
  }catch(PDOException $x){$err=$x->errorInfo[1]==1062?'That dose is already recorded for this patient.':'Could not save.';}}
if($P)$rec=$q("SELECT r.*,u.name gb FROM immunization_records r LEFT JOIN users u ON u.id=r.given_by WHERE r.patient_id=? ORDER BY r.given_at,r.id",[$pid]);
if($P&&isset($_GET['print'])){echo doc_open('Immunization and nutrition card',$P);echo '<table><tr><th>Vaccine / item<th>Dose<th>Date<th>Batch<th>Given by</tr>';foreach($rec as $r)echo '<tr><td>'.e($r['item']).'<td>'.e($r['dose_no']).'<td>'.e($r['given_at']).'<td>'.e($r['batch_no']).'<td>'.e($r['gb']);echo '</table><table><tr><th>Nutrition check<th>Wt kg<th>Ht cm<th>MUAC<th>Result</tr>';
  foreach($q('SELECT * FROM nutrition_assessments WHERE patient_id=? ORDER BY id',[$pid]) as $n)echo '<tr><td>'.substr($n['assessed_at'],0,10).'<td>'.e($n['weight_kg']).'<td>'.e($n['height_cm']).'<td>'.e($n['muac_mm']).'<td>'.e($n['classification']);echo '</table>';echo doc_close('immunization.php?pid='.$pid);exit;}
head('Immunization & Nutrition');if($msg)echo '<p class=ok>'.e($msg).'</p>';if($err)echo '<p class=err>'.e($err).'</p>';
echo '<div class=card><form style="display:flex;gap:8px"><input name=q value="'.e($sq).'" placeholder="Find a patient: name, patient no, ID or phone"><button style="margin:0">Find</button></form>';
if($sq!==''){$l="%$sq%";foreach($q('SELECT id,patient_no,first_name,last_name,dob FROM patients WHERE first_name LIKE ? OR last_name LIKE ? OR patient_no LIKE ? OR id_number LIKE ? OR phone LIKE ? LIMIT 10',[$l,$l,$l,$l,$l]) as $r)echo '<div><a href="immunization.php?pid='.$r['id'].'">'.e($r['patient_no'].' '.$r['first_name'].' '.$r['last_name'].' (born '.$r['dob'].')').'</a></div>';}echo '</div>';
if(!$P){echo '<div class=card><h3>Children with overdue vaccines</h3>';$kids=$q('SELECT id,patient_no,first_name,last_name,dob FROM patients WHERE dob>=DATE_SUB(CURDATE(),INTERVAL 5 YEAR) ORDER BY dob DESC LIMIT 150');$g=[];
  foreach($q("SELECT patient_id,item,dose_no FROM immunization_records WHERE kind='vaccine'") as $r)$g[$r['patient_id']][$r['item'].'|'.(int)$r['dose_no']]=1;$n=0;
  foreach($kids as $k){$w=(int)floor((time()-strtotime($k['dob']))/604800);$od=[];foreach($SCH as $s)if($w>$s[2]+4&&empty($g[$k['id']][$s[0].'|'.$s[1]]))$od[]=$s[0].' '.$s[1];
    if($od&&$n++<40)echo '<div><a href="immunization.php?pid='.$k['id'].'">'.e($k['patient_no'].' '.$k['first_name'].' '.$k['last_name']).'</a> <span class=err>'.count($od).' overdue:</span> '.e(implode(', ',$od)).'</div>';}
  if(!$n)echo '<p>No overdue vaccines found.</p>';echo '</div>';foot();exit;}
echo '<div class=card><h3>'.e($P['first_name'].' '.$P['last_name'].' ('.$P['patient_no'].')').'</h3>Age: '.$di->y.' years '.$di->m.' months | <a href="immunization.php?pid='.$pid.'&print=1" target=_blank>Print card</a> | <a href="immunization.php">Back to search</a></div>';
$given=[];foreach($rec as $r)if($r['kind']=='vaccine')$given[$r['item'].'|'.(int)$r['dose_no']]=$r;
if($mo<60){echo '<div class=card><h3>Child immunization schedule</h3><table><tr><th>Vaccine<th>Dose<th>Due date<th>Status<th></tr>';
  foreach($SCH as $s){$k=$s[0].'|'.$s[1];$due=date('Y-m-d',strtotime($P['dob'].' +'.($s[2]*7).' days'));echo '<tr><td>'.e($s[0]).'<td>'.$s[1].'<td>'.$due.'<td>';
    if(isset($given[$k]))echo 'Given '.e($given[$k]['given_at']).' (batch '.e($given[$k]['batch_no']).')<td>';
    else{$st=$wk<$s[2]?'Upcoming':($wk<=$s[2]+4?'<b>Due now</b>':'<b class=err>Overdue</b>');echo $st.'<td>';if($wk>=$s[2])echo '<form method=post style="display:flex;gap:4px">'.field().'<input type=hidden name=pid value='.$pid.'><input type=hidden name=vac value=1><input type=hidden name=item value="'.e($s[0]).'"><input type=hidden name=dose value='.$s[1].'><input name=batch placeholder="Batch no" style="width:110px"><button style="margin:0">Give</button></form>';}}
  echo '</table></div>';}
$last=function($kind)use($rec){$x=null;foreach($rec as $r)if($r['kind']==$kind)$x=$r;return $x;};$va=$last('vitamin_a');$dw=$last('deworming');
echo '<div class=g><div class=card><h3>Vitamin A</h3><p>'.($va?'Last given '.e($va['given_at']).', next due '.e($va['next_due']):'Not given yet').($mo<6||$mo>=60?'<br><small>Routine doses are for children 6 to 59 months.</small>':'').'</p><form method=post>'.field().'<input type=hidden name=pid value='.$pid.'><input type=hidden name=vita value=1><input name=batch placeholder="Batch no"><button>Give vitamin A</button></form></div>
<div class=card><h3>Deworming (albendazole)</h3><p>'.($dw?'Last given '.e($dw['given_at']).', next due '.e($dw['next_due']):'Not given yet').($mo<12?'<br><small>Routine deworming starts at 12 months.</small>':'').'</p><form method=post>'.field().'<input type=hidden name=pid value='.$pid.'><input type=hidden name=worm value=1><input name=batch placeholder="Batch no"><button>Give deworming</button></form></div>
<div class=card><h3>Record another vaccine</h3><form method=post>'.field().'<input type=hidden name=pid value='.$pid.'><input type=hidden name=vac value=1><input name=item placeholder="e.g. Tetanus toxoid, HPV, COVID-19" required><input name=dose type=number min=0 max=10 placeholder="Dose no"><input name=batch placeholder="Batch no"><button>Record</button></form></div></div>';
echo '<div class=card><h3>Nutrition check</h3><form method=post class=g>'.field().'<input type=hidden name=pid value='.$pid.'><input type=hidden name=nut value=1><div><label>Weight (kg)</label><input name=w type=number step=0.1></div><div><label>Height / length (cm)</label><input name=h type=number step=0.1></div><div><label>MUAC (mm, children 6 to 59 months)</label><input name=muac type=number></div><div><label style="font-weight:400"><input type=checkbox name=oed style="width:auto"> Swelling of both feet (oedema)</label></div><div><label>Notes</label><input name=notes></div><div><button>Save assessment</button></div></form>
<table><tr><th>Date<th>Weight<th>Height<th>MUAC<th>Result<th>Advice</tr>';foreach($q('SELECT * FROM nutrition_assessments WHERE patient_id=? ORDER BY id DESC LIMIT 10',[$pid]) as $n)echo '<tr><td>'.substr($n['assessed_at'],0,10).'<td>'.e($n['weight_kg']).'<td>'.e($n['height_cm']).'<td>'.e($n['muac_mm']).'<td>'.(strpos($n['classification'],'SAM')===0?'<b class=err>'.e($n['classification']).'</b>':e($n['classification'])).'<td>'.e($n['advice']);echo '</table></div>';
echo '<div class=card><h3>Everything given</h3><table><tr><th>Item<th>Dose<th>Date<th>Batch<th>Next due<th>By</tr>';foreach(array_reverse($rec) as $r)echo '<tr><td>'.e($r['item']).'<td>'.e($r['dose_no']).'<td>'.e($r['given_at']).'<td>'.e($r['batch_no']).'<td>'.e($r['next_due']).'<td>'.e($r['gb']);echo '</table></div>';foot();
